require "rails_helper"

RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  # "A load replaces the tables in one transaction, so an interrupted load leaves them unchanged"
  it "leaves every prepared table as it was when a load fails midway on an audit row whose entry is missing" do
    connection = ActiveRecord::Base.connection
    store = described_class.new(connection: connection)
    stamp = Time.utc(2026, 1, 1, 12, 0, 0, 123_456)
    connection.execute(<<~SQL.squish)
      INSERT INTO entries (id, company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (5, 1, 2, 1, 1, '2026-01-01', 1.5, 'unbilled', now(), now())
    SQL
    baseline = %w[entries reservations invoice_operations entry_audits idempotency_records].index_with do |table|
      connection.select_all("SELECT * FROM #{table} ORDER BY 1, 2").to_a
    end
    expect(baseline["entries"].pluck("id")).to eq([5])

    entry = {
      "id" => 10, "company_id" => 1, "version" => 3, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
      "work_date" => Date.new(2026, 1, 2), "duration" => 0.1 + 0.2, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => stamp, "updated_at" => stamp
    }
    # The audit row points at an entry the checkpoint does not carry, so the
    # insert of entry_audits fails after entries were already replaced.
    orphan_audit = {
      "id" => 1, "company_id" => 1, "entry_id" => 999, "actor_type" => "User", "actor_id" => 7,
      "actor_name" => nil, "action" => "update", "before" => nil, "after" => { "note" => "x" },
      "entry_created_at" => stamp, "created_at" => stamp
    }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: {
        "entries" => [entry], "reservations" => [], "invoice_operations" => [],
        "entry_audits" => [orphan_audit], "idempotency_records" => []
      }
    )

    expect { store.load_checkpoint(checkpoint) }.to raise_error(StandardError)

    after = baseline.keys.index_with do |table|
      connection.select_all("SELECT * FROM #{table} ORDER BY 1, 2").to_a
    end
    expect(after).to eq(baseline)
  end
end

