      "work_date" => Date.new(2026, 1, 2), "duration" => 2.0, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => stamp, "updated_at" => stamp
    }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
