RSpec.describe Timekeeping::Handoff::MonolithStore, :without_transaction do
  # "Load the same checkpoint twice and get equal counts and checksums; a row seeded before the load is gone afterwards."
  it "loading the same checkpoint twice removes a stray row and never doubles rows" do
    connection = ActiveRecord::Base.connection
    store = described_class.new(connection: connection)
    stamp = Time.utc(2026, 1, 1, 12, 0, 0, 500_000)
    connection.execute(<<~SQL.squish)
      INSERT INTO entries (id, company_id, version, project_id, user_id, work_date, duration, bill_status, created_at, updated_at)
      VALUES (77, 2, 1, 1, 1, '2026-01-01', 9.0, 'unbilled', now(), now())
    SQL
    entry = {
      "id" => 10, "company_id" => 1, "version" => 4, "project_id" => 1, "user_id" => 1, "agent_id" => nil,
      "work_date" => Date.new(2026, 1, 2), "duration" => 0.1 + 0.2, "note" => "", "bill_status" => "unbilled",
      "review_status" => "not_required", "locked" => false, "source" => "manual", "source_metadata" => {},
      "external_run_id" => nil, "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
      "discarded_at" => nil, "created_at" => stamp, "updated_at" => stamp
    }
    receipt = {
      "id" => 1, "company_id" => 1, "actor_type" => "User", "actor_id" => 7, "operation" => "create_entry",
      "key" => "k-1", "fingerprint" => "f", "status" => 201, "body" => "{ \"b\":1,  \"a\":2 }", "created_at" => stamp
    }
    checkpoint = Timekeeping::Handoff::Checkpoint.build(
      tables: {
        "entries" => [entry], "reservations" => [], "invoice_operations" => [],
        "entry_audits" => [], "idempotency_records" => [receipt]
      }
    )

    store.load_checkpoint(checkpoint)
    first = store.export_checkpoint.digest
    store.load_checkpoint(checkpoint)
    second = store.export_checkpoint.digest

    expect(connection.select_values("SELECT id FROM entries ORDER BY id")).to eq([10])
    expect(connection.select_value("SELECT count(*) FROM idempotency_records")).to eq(1)
    expect(first).to eq(checkpoint.digest)
    expect(second).to eq(checkpoint.digest)
  end
end

